19	package org.apache.pinot.segment.local.function;
20	
21	import com.google.common.base.Preconditions;
22	import com.google.common.base.Splitter;
23	import groovy.lang.Binding;
24	import groovy.lang.GroovyShell;
25	import groovy.lang.Script;
26	import java.util.Collections;
27	import java.util.List;
28	import java.util.regex.Matcher;
29	import java.util.regex.Pattern;
30	import org.apache.pinot.spi.data.readers.GenericRow;
31	
32	
33	/**
34	 * An {@link FunctionEvaluator} for evaluating transform function expressions of a Schema field spec written in Groovy.
35	 * GroovyShell is used to execute expressions.
36	 *
37	 * The transform expression must follow the convention Groovy({expression}, arguments1, argument2...)
38	 * For example:
39	 * "dimensionFieldSpecs": [
40	 *     {
41	 *       "name": "fullName",
42	 *       "dataType": "STRING",
43	 *       "transformFunction": "Groovy({firstName+' '+lastName}, firstName, lastName)"
44	 *     }
45	 *  ]
46	 */
47	public class GroovyFunctionEvaluator implements FunctionEvaluator {
48	
49	  private static final String GROOVY_EXPRESSION_PREFIX = "Groovy";
50	  private static final String GROOVY_FUNCTION_REGEX = "Groovy\\(\\{(?<script>.+)}(,(?<arguments>.+))?\\)";
51	  private static final Pattern GROOVY_FUNCTION_PATTERN =
52	      Pattern.compile(GROOVY_FUNCTION_REGEX, Pattern.CASE_INSENSITIVE);
53	  private static final String ARGUMENTS_GROUP_NAME = "arguments";
54	  private static final String SCRIPT_GROUP_NAME = "script";
55	  private static final String ARGUMENTS_SEPARATOR = ",";
56	
57	  private final List<String> _arguments;
58	  private final int _numArguments;
59	  private final Binding _binding;
60	  private final Script _script;
61	  private final String _expression;
62	
63	  public GroovyFunctionEvaluator(String closure) {
64	    _expression = closure;
65	    Matcher matcher = GROOVY_FUNCTION_PATTERN.matcher(closure);
66	    Preconditions.checkState(matcher.matches(), "Invalid transform expression: %s", closure);
67	    String arguments = matcher.group(ARGUMENTS_GROUP_NAME);
68	    if (arguments != null) {
69	      _arguments = Splitter.on(ARGUMENTS_SEPARATOR).trimResults().splitToList(arguments);
70	    } else {
71	      _arguments = Collections.emptyList();
72	    }
73	    _numArguments = _arguments.size();
74	    _binding = new Binding();
75	    _script = new GroovyShell(_binding).parse(matcher.group(SCRIPT_GROUP_NAME));
76	  }
77	
78	  public static String getGroovyExpressionPrefix() {
79	    return GROOVY_EXPRESSION_PREFIX;
80	  }
81	
82	  @Override
83	  public List<String> getArguments() {
84	    return _arguments;
85	  }
86	
87	  @Override
88	  public Object evaluate(GenericRow genericRow) {
89	    boolean hasNullArgument = false;
90	    for (String argument : _arguments) {
91	      Object value = genericRow.getValue(argument);
92	      if (value == null) {
93	        hasNullArgument = true;
94	      }
95	      _binding.setVariable(argument, value);
96	    }
97	    try {
98	      return _script.run();
99	    } catch (Exception e) {
100	      if (hasNullArgument) {
101	        return null;
102	      } else {
103	        throw e;
104	      }
105	    }
106	  }
107	
108	  @Override
109	  public Object evaluate(Object[] values) {
110	    for (int i = 0; i < _numArguments; i++) {
111	      _binding.setVariable(_arguments.get(i), values[i]);
112	    }
113	    return _script.run();
114	  }
115	
116	  @Override
117	  public String toString() {
118	    return _expression;
119	  }
120	}
